function evaluate(expr: string): number {
  const stack: number[] = [];
  let total = 0, sign = 1, num = 0;
  for (const ch of expr) {
    if (ch >= "0" && ch <= "9") {
      num = num * 10 + (ch.charCodeAt(0) - 48);
    } else if (ch === "+" || ch === "-") {
      total += sign * num;
      num = 0;
      sign = ch === "+" ? 1 : -1;
    } else if (ch === "(") {
      stack.push(total, sign);
      total = 0;
      sign = 1;
    } else if (ch === ")") {
      total += sign * num;
      num = 0;
      const savedSign = stack.pop()!;
      const savedTotal = stack.pop()!;
      total = savedTotal + savedSign * total;
    }
  }
  return total + sign * num;
}

