            elif ch == "(":
                stack.append((total, sign))
                total, sign = 0, 1
            elif ch == ")":
                total += sign * num
                num = 0
                saved_total, saved_sign = stack.pop()
                total = saved_total + saved_sign * total
        return total + sign * num

