function evaluate(expr: string): number {
  const signs = [1]; // combined sign of the bracket we are inside
  let total = 0, sign = 1, i = 0;
  while (i < expr.length) {
    const ch = expr[i];
    if (ch >= "0" && ch <= "9") {
      let num = 0;
      while (i < expr.length && expr[i] >= "0" && expr[i] <= "9") num = num * 10 + (expr.charCodeAt(i++) - 48);
      total += sign * num;
      continue;
    }
    if (ch === "+") sign = signs[signs.length - 1];
    else if (ch === "-") sign = -signs[signs.length - 1];
    else if (ch === "(") signs.push(sign);
    else if (ch === ")") signs.pop();
    i++;
  }
  return total;
}

